    // For radius r + 0.7f, rows absZ=0..r start at index r*(r+1)/2.
    // Each ushort is the greatest x satisfying the single-precision circle bound.
    internal static class RimKataRingGeometry
    {
        internal const int MaximumPrecomputedRing = 256;
        private const float PrecomputedPadding = 0.7f;

        internal static bool TryGetCircleRowOffset(float radius, out int offset)
        {
            int ring = Mathf.FloorToInt(radius);
            if ((uint)ring <= MaximumPrecomputedRing
                && radius == ring + PrecomputedPadding)
            {
                offset = ring * (ring + 1) / 2;
                return true;
            }

            offset = -1;
            return false;
        }

